/* ================= componentes (estilo shadcn) ================= */
const OPTS={p:{},m:{},x:{}};let SCOPE='p',optN=0;
const regOpts=o=>{const k=SCOPE+(++optN);OPTS[SCOPE][k]=o;return k};
const optLabel=o=>o?`${o.icon?`<span class="oi ${o.ib||''}" style="width:22px;height:22px">${ic(o.icon)}</span>`:''}<span style="overflow:hidden;text-overflow:ellipsis">${esc(o.l)}</span>`:'';
function sel(name,opts,val,o={}){const k=regOpts(opts);const cur=opts.find(x=>String(x.v)===String(val));
  return `<div class="ui-sel" data-sel="${k}" ${o.search||opts.length>8?'data-search':''} ${o.create?`data-create="${o.create===1||o.create===true?'cat':o.create}"`:''}><input type="hidden" name="${name}" id="${o.id||'s_'+name+'_'+k}" value="${esc(cur?cur.v:'')}" ${o.attrs||''} ${o.req?'data-req':''}><button type="button" class="ui-trigger" data-sel-btn aria-haspopup="listbox"><span class="tv ${cur?'':'ph'}">${cur?optLabel(cur):esc(o.ph||'Selecciona…')}</span>${ic('chevron-down')}</button></div>`}
function datep(name,val,o={}){const v=val||'';return `<div class="ui-date"><input type="hidden" name="${name}" id="${o.id||'d_'+name+'_'+(++optN)}" value="${esc(v)}" ${o.attrs||''}><button type="button" class="ui-trigger" data-date-btn><span class="tv ${v?'':'ph'}">${ic('calendar')}<span>${v?fdate(parse(v)):esc(o.ph||'Elige una fecha')}</span></span>${ic('chevron-down')}</button></div>`}
function money(name,val,o={}){const dec=!!o.dec;return `<div class="ui-money"><span class="cur">${o.cur||'$'}</span><input type="text" inputmode="${dec?'decimal':'numeric'}" autocomplete="off" data-money${dec?'="dec"':''} name="${name}" id="${o.id||'m_'+name+'_'+(++optN)}" value="${val===''||val==null?'':fmtMoneyInput(val,dec)}" placeholder="${o.ph||'0'}" ${o.req?'required':''} ${o.attrs||''}></div>`}
const txt=(name,val,o={})=>`<input class="inp" type="${o.type||'text'}" name="${name}" id="${o.id||'t_'+name+'_'+(++optN)}" value="${esc(val??'')}" placeholder="${esc(o.ph||'')}" ${o.req?'required':''} ${o.attrs||''} ${o.max?`maxlength="${o.max}"`:''}>`;
const num=(name,val,o={})=>`<input class="inp" type="text" inputmode="decimal" data-num name="${name}" id="${o.id||'n_'+name+'_'+(++optN)}" value="${esc(val??'')}" placeholder="${esc(o.ph||'')}" ${o.req?'required':''} ${o.attrs||''}>`;
const tip=t=>`<span class="tip" tabindex="0" data-tip="${esc(t)}">?</span>`;
const field=(label,ctrl,o={})=>`<div class="f ${o.cls||''}" ${o.show?`data-show="${o.show}"`:''}><label>${label}${o.tip?tip(o.tip):''}</label>${ctrl}${o.hint?`<span class="hint">${o.hint}</span>`:''}</div>`;
const hidden=(name,val)=>`<input type="hidden" name="${name}" value="${esc(val)}">`;
const pick=(name,items,val,cls='choice')=>items.map(it=>`<button type="button" class="${cls} ${String(it.v)===String(val)?'on':''}" data-pick="${name}" data-v="${esc(it.v)}">${cls==='choice'?`${it.rec?`<span class="pill info rec">Recomendado</span>`:''}${it.iso?`<span class="ci" style="background:none">${isoIcon(it.iso,36)}</span>`:it.icon?`<span class="ci ${it.ib||'t-blue'}">${ic(it.icon)}</span>`:''}<div><b>${it.l}</b>${it.d?`<span>${it.d}</span>`:''}</div>`:`${it.icon?ic(it.icon):''}${it.l}`}</button>`).join('');
const chips=(name,vals,cur,fmt=v=>v)=>`<div class="chips">${vals.map(v=>`<button type="button" class="chip ${String(v)===String(cur)?'on':''}" data-chip="${name}" data-v="${v}">${fmt(v)}</button>`).join('')}</div>`;
const quienOpts=()=>[{v:'familia',l:'Toda la familia',icon:'users'},...S.perfil.miembros.map(m=>({v:m.id,l:m.nombre,icon:'user'}))];
const quienName=id=>id==='familia'?'Familia':(S.perfil.miembros.find(m=>m.id===id)?.nombre||'—');
const catOpts=()=>S.cfg.categorias.map(c=>({v:c.nombre,l:c.nombre,icon:c.icon,h:{n:'Necesidad',g:'Gusto',a:'Ahorro'}[c.grupo]}));
const medioOpts=()=>S.cfg.medios.map(m=>({v:m.nombre,l:m.nombre,icon:m.icon}));
const monOpts=()=>['COP','USD','EUR'].map(m=>({v:m,l:m==='COP'?'Pesos (COP)':m==='USD'?'Dólares (USD)':'Euros (EUR)'}));
const contactOpts=()=>S.contactos.map(c=>({v:c.id,l:c.nombre,icon:c.tipo==='empresa'?'building-2':'user-round',h:[c.relacion,c.telefono].filter(Boolean).join(' · ')}));
const entOpts=()=>S.cfg.entidades.map(e=>({v:e.id,l:e.nombre,icon:'landmark',h:[e.tipo,e.nit?'NIT '+e.nit:''].filter(Boolean).join(' · ')}));
const EMISO={'receipt':'gastos','house':'fijos','repeat':'suscripciones','hand-coins':'me-deben','landmark':'le-debo','users':'contactos','target':'metas','trending-up':'inversiones','briefcase':'ingresos','credit-card':'tarjetas','split':'compartidos','baby':'mesadas','calendar':'calendario','gauge':'indicadores','handshake':'me-deben','bell':'recordatorios','message-circle-question':'consejero','lightbulb':'consejero','circle-check':'retos','party-popper':'retos'};
const empty=(icon,t,btn='')=>`<div class="empty">${EMISO[icon]?isoIcon(EMISO[icon],72):`<span class="ei">${ic(icon)}</span>`}<div>${t}</div>${btn}</div>`;
const pageH=(icon,bg,t,p,act='')=>`<div class="page-h">${ISO[view()]?`<span class="pic isop">${isoIcon(view(),56)}</span>`:`<span class="pic ${bg}">${ic(icon)}</span>`}<div><h1>${t}</h1>${p?`<p>${p}</p>`:''}</div><div class="act"><button class="btn ghost help-btn" data-act="help">${ic('circle-help')}Cómo funciona</button>${act}</div></div>`+sampleBar()+helpStrip(view());
const sampleBar=()=>S.sample?`<div class="alert info"><span class="ai">${ic('info')}</span><div style="flex:1"><b>Estás viendo datos de ejemplo</b>Las cifras son ilustrativas y no se guardan. Empieza tu libro en blanco o usa el ejemplo como punto de partida.</div><div class="row" style="display:flex;gap:8px;flex-wrap:wrap;align-self:center"><button class="btn sm" data-act="keep">Usar como base</button><button class="btn sm pri" data-act="blank">Empezar en blanco</button></div></div>`:'';
const kpi=(icon,t,l,v,s,cls='')=>`<div class="card kpi"><span class="ki ${t}">${ic(icon)}</span><div><div class="kl">${l}</div><div class="kv ${cls}">${v}</div>${s?`<div class="ks">${s}</div>`:''}</div></div>`;
const bar=(l,v,max,color,val,icon)=>`<div class="bar"><div class="bh"><span>${icon?ic(icon):''}${l}</span><b class="num">${val}</b></div><div class="track"><i style="width:${max?Math.min(Math.max(v,0)/max,1)*100:0}%;background:${color||'var(--blue)'}"></i></div></div>`;
const av=(name,cls='')=>`<span class="avatar ${cls} ${hashC(name)}">${esc(initials(name))}</span>`;
const alertBox=(lvl,icon,t,b)=>`<div class="alert ${lvl}"><span class="ai">${ic(icon)}</span><div><b>${t}</b>${b}</div></div>`;
const stPill=s=>`<span class="pill ${s[0]}">${s[1]}</span>`;
const dateBox=d=>`<span class="datebox"><span>${MES[d.getMonth()]}</span><b>${d.getDate()}</b></span>`;

const V={};
/* ================= menú (estilo sidebar de shadcn) ================= */
const MENU=[
 {sec:'General'},
 {id:'puesta',l:'Puesta en marcha',icon:'rocket',bg:'b-grad',cond:()=>!setupDone()},
 {id:'inicio',l:'Inicio',icon:'house',bg:'b-blue'},
 {id:'consejero',l:'Consejero IA',icon:'sparkles',bg:'b-grad'},
 {sec:'Finanzas'},
 {g:'dinero',l:'Mi dinero',icon:'wallet',bg:'b-green',items:[['balance','Balance y quincenas','scale'],['ingresos','Ingresos','arrow-down-to-line'],['gastos','Gastos y hormiga','receipt'],['fijos','Gastos fijos','house'],['tarjetas','Tarjetas de crédito','credit-card'],['suscripciones','Suscripciones','repeat'],['correo','Correo del banco','mail'],['importar','Importar extractos','file-up']]},
 {g:'prestamos',l:'Préstamos y deudas',icon:'handshake',bg:'b-amber',items:[['me-deben','Me deben','hand-coins'],['le-debo','Le debo','landmark'],['contactos','Contactos','users'],['estrategia','Salir de deudas','trending-down']]},
 {g:'plan',l:'Planeación',icon:'target',bg:'b-violet',items:[['presupuesto','Presupuesto 50/30/20','chart-pie'],['flujo','Flujo de caja','chart-line'],['metas','Metas y emergencia','piggy-bank'],['retos','Retos de ahorro','trophy'],['primas','Primas y cesantías','gift'],['familia','Por miembro','users'],['mesadas','Mesada de los hijos','baby'],['compartidos','Gastos compartidos','split']]},
 {id:'inversiones',l:'Inversiones',icon:'trending-up',bg:'b-teal'},
 {sec:'Seguimiento'},
 {g:'agenda',l:'Agenda',icon:'calendar-days',bg:'b-red',items:[['recordatorios','Próximos pagos','bell'],['calendario','Calendario fiscal','calendar']]},
 {g:'informes',l:'Informes',icon:'chart-column',bg:'b-pink',items:[['indicadores','Salud financiera','gauge'],['reportes','Reportes y resumen IA','file-text'],['renta','Asistente de renta','file-check']]},
 {sec:'Soporte'},
 {g:'ayuda',l:'Ayuda',icon:'life-buoy',bg:'b-blue',items:[['novedades','Novedades','megaphone'],['faq','Preguntas frecuentes','circle-help'],['manual','Manual e instructivos','book-open']]},
 {sec:'Configuración'},
 {id:'perfil',l:'Perfil',icon:'user',bg:'b-gray'},
 {id:'ajustes',l:'Ajustes',icon:'settings',bg:'b-gray'}];
