const MENUPAGES=()=>MENU.filter(x=>!x.sec&&(!x.cond||x.cond())).flatMap(x=>x.id?[[x.id,x.l,x.icon]]:x.items.map(i=>[i[0],i[1],i[2]]));
const CTABS=[['inicio','house','Inicio'],['consejero','sparkles','Consejero IA'],['gastos','receipt','Gastos'],['me-deben','handshake','Préstamos'],['recordatorios','calendar-days','Próximos pagos']];
let NAVOPEN=(()=>{const n=store.get(KNAV,{});Object.keys(n).filter(k=>n[k]).slice(1).forEach(k=>n[k]=false);return n})();
const sbCollapsed=()=>document.body.classList.contains('sb-col');
function renderNav(v){const nVenc=agenda().filter(x=>x.st==='bad'&&x.dir==='pagar').length,H=hormigas();const sp=setupProgress();const badge={recordatorios:nVenc,gastos:H.over?'!':0,puesta:`${sp.done}/${sp.total}`};
  const parentOf=Object.fromEntries(MENU.filter(x=>x.g).flatMap(x=>x.items.map(i=>[i[0],x.g])));const col=sbCollapsed();
  const body=MENU.filter(x=>!x.cond||x.cond()).map(x=>{if(x.sec)return `<div class="sb-label">${x.sec}</div>`;
    if(x.id)return `<a class="sb-item ${v===x.id?'on':''}" href="#${x.id}" ${col?`title="${x.l}"`:''}><span class="sb-ic">${isoIcon(x.id,22)||ic(x.icon)}</span><span class="sb-l">${x.l}</span>${badge[x.id]?`<span class="sb-bdg ${x.id==='puesta'?'info':''}">${badge[x.id]}</span>`:''}</a>`;
    const act=parentOf[v]===x.g,open=!col&&(NAVOPEN[x.g]!==undefined?NAVOPEN[x.g]:act);const sb=x.items.reduce((a,i)=>a+(+badge[i[0]]||0),0);
    return `<button class="sb-item ${act&&(col||!open)?'on':''} ${open?'open':''}" data-act="navg" data-g="${x.g}" aria-expanded="${open}" ${col?`title="${x.l}"`:''}><span class="sb-ic">${isoIcon(GISO[x.g],22)||ic(x.icon)}</span><span class="sb-l">${x.l}</span>${!open&&sb?`<span class="sb-bdg">${sb}</span>`:''}<span class="sb-chev">${ic('chevron-right')}</span></button><div class="sb-sub ${open?'open':''}">${x.items.map(i=>`<a href="#${i[0]}" class="${v===i[0]?'on':''}">${isoIcon(i[0],18)}${i[1]}${badge[i[0]]?`<span class="sb-bdg">${badge[i[0]]}</span>`:''}</a>`).join('')}</div>`}).join('');
  const N0=notifs(),rd0=new Set(store.get(KREAD,[])),un0=N0.filter(n=>!rd0.has(n.id)).length;
  document.getElementById('side').innerHTML=`<div class="sb-head"><button class="sb-brand" data-act="libroMenu" title="Cambiar de libro">${BOOK==='principal'?`<span class="sb-logo isol">${isoIcon('mirai',34)}</span>`:`<span class="sb-logo">${ic(libroActual().icon||'book-open')}</span>`}<span class="sb-l"><b>${esc(libroActual().nombre)}</b><small>Mirai · Tu futuro financiero</small></span><span class="sb-chev2">${ic('chevrons-up-down')}</span></button><button class="sb-tog" data-act="sbToggle" title="${col?'Expandir':'Contraer'} el menú (Ctrl+B)" aria-label="${col?'Expandir':'Contraer'} el menú">${ic(col?'panel-left-open':'panel-left-close')}</button></div>
    <div class="sb-tools"><button class="sb-create" data-act="create" ${col?'title="Agregar"':''}>${ic('circle-plus')}<span>Agregar</span><kbd class="kbd">N</kbd></button><label class="sb-search" for="q" ${col?'data-act="sbSearch" title="Buscar (Ctrl+K)"':''}>${ic('search')}<input id="q" placeholder="Buscar…" autocomplete="off"><kbd class="kbd">Ctrl K</kbd></label>
    <button class="sb-item sb-bell" data-act="bell" id="bell" ${col?'title="Notificaciones"':''}><span class="sb-ic">${ic('bell')}${un0?`<span class="dot">${un0>9?'9+':un0}</span>`:''}</span><span class="sb-l">Notificaciones</span>${un0?`<span class="sb-bdg">${un0}</span>`:''}</button></div>
    <nav class="sb-body" aria-label="Menú principal">${body}</nav>
    <div class="sb-foot"><div class="sb-sync" title="${esc(SYNC.s)}"><span class="syncp ${SYNC.cls}" id="syncP">${esc(SYNC.t)}</span><span class="sb-l note" id="syncS">${esc(SYNC.s)}</span></div>
    <button class="sb-user" data-act="userMenu" aria-label="Menú de usuario">${av(S.perfil.nombre||'?','sm')}<span class="sb-l"><b>${esc(S.perfil.nombre||'Tu perfil')}</b><small>${esc(S.perfil.ocupacion||'Libro familiar')}</small></span><span class="sb-chev2">${ic('chevrons-up-down')}</span></button></div>`;
  {let sec='',grp=null,pg=null,cs='';for(const x of MENU){if(x.sec){cs=x.sec;continue}if(x.id===v){sec=cs;pg=x.l;break}if(x.g){const it=x.items.find(i=>i[0]===v);if(it){sec=cs;grp=x;pg=it[1];break}}}document.getElementById('crumbs').innerHTML=`<a href="#inicio" class="mid">${esc(libroActual().nombre)}</a>${ic('chevron-right','mid')}${sec?`<span class="mid">${sec}</span>${ic('chevron-right','mid')}`:''}${grp?`<span class="mid">${grp.l}</span>${ic('chevron-right','mid')}`:''}<span class="cur">${esc(pg||'Inicio')}</span>`}
  
  const wm=document.getElementById('wordmark');if(wm&&!wm.firstChild)wm.innerHTML=`${isoIcon('mirai',24)}<span>Mirai</span>`;const me=document.getElementById('meAv');if(me){me.textContent=initials(S.perfil.nombre);me.className='avatar '+hashC(S.perfil.nombre||'?')}}

/* ================= puesta en marcha ================= */
const SETUP=[
 {k:'perfil',icon:'user',t:'Cuéntanos quién eres',d:'Tu nombre y, si quieres, los integrantes de tu familia. Así personalizamos el libro y el presupuesto por miembro.',done:()=>!!S.perfil.nombre,act:'go:perfil',btn:'Completar perfil'},
 {k:'ingresos',icon:'arrow-down-to-line',t:'Registra tus ingresos',d:'Tu salario, honorarios o arriendos, y cada cuánto te pagan. Es lo más importante: sin esto no podemos decirte cuánto te queda ni si te alcanza para algo.',done:()=>S.ingresos.length>0,act:'modal:ingreso',btn:'Agregar ingreso'},
 {k:'cuentas',icon:'landmark',t:'Agrega tus cuentas y efectivo',d:'Cuánto tienes hoy en el banco, en Nequi o en efectivo. Sirve para calcular tu colchón de emergencia y tu patrimonio.',done:()=>S.activos.some(a=>/^11/.test(a.cod)),act:'modal:activo',btn:'Agregar cuenta'},
 {k:'fijos',icon:'house',t:'Anota tus gastos fijos',d:'Arriendo, servicios, administración, colegio… Te avisaremos antes de cada fecha de pago.',done:()=>S.fijos.length>0,act:'modal:fijo',btn:'Agregar gasto fijo',skip:'No tengo gastos fijos'},
 {k:'deudas',icon:'landmark',t:'Registra tus deudas y créditos',d:'Créditos con bancos, tarjetas o plata que le debes a alguien. Verás cuánto te falta y cuándo pagar.',done:()=>S.pagar.length>0,act:'modal:loan:pagar',btn:'Agregar deuda',skip:'No tengo deudas'},
 {k:'prestamos',icon:'hand-coins',t:'¿Le prestaste plata a alguien?',d:'Registra a quién y cómo te va a pagar, para que no se te olvide cobrar.',done:()=>S.cobrar.length>0,act:'modal:loan:cobrar',btn:'Registrar préstamo',skip:'Nadie me debe'},
 {k:'presupuesto',icon:'chart-pie',t:'Ponle tope a tus gastos',d:'Escribe cuánto quieres gastar como máximo en mercado, transporte, restaurantes… Te avisamos si te acercas al límite.',done:()=>S.cfg.categorias.some(c=>+c.tope>0),act:'go:presupuesto',btn:'Definir presupuesto',skip:'Lo hago después'},
 {k:'gasto',icon:'receipt',t:'Registra tu primer gasto',d:'Escribe en qué gastaste y la categoría se pone sola. Hazlo cada día: toma segundos y es lo que hace funcionar todo.',done:()=>S.gastos.length>0,act:'modal:gasto',btn:'Registrar gasto'},
 {k:'meta',icon:'target',t:'Crea una meta de ahorro',d:'Un viaje, la cuota inicial de la casa o tu fondo de emergencia. Te decimos cuánto guardar cada mes.',done:()=>S.metas.length>0,act:'modal:meta',btn:'Crear meta',skip:'Ahora no'}];
function setupProgress(){const sk=S.setup?.skip||{};const st=SETUP.map(s=>({...s,ok:s.done(),skipped:!s.done()&&!!sk[s.k]}));const done=st.filter(s=>s.ok||s.skipped).length;return{st,done,total:SETUP.length,next:st.find(s=>!s.ok&&!s.skipped)}}
const SISO={perfil:'perfil',ingresos:'ingresos',cuentas:'balance',fijos:'fijos',deudas:'le-debo',prestamos:'me-deben',presupuesto:'presupuesto',gasto:'gastos',meta:'metas'};
const setupDone=()=>{if(S.sample)return true;const p=setupProgress();return p.done===p.total||!!S.setup?.dismissed};
V.puesta=()=>{const p=setupProgress(),nombre=(S.perfil.nombre||'').split(' ')[0],first=p.done===0;
  const act=s=>{const [t,a,b]=s.act.split(':');return t==='go'?`data-go="${a}"`:`data-modal="${a}" ${b?`data-kind="${b}"`:''}`};
  return `<div class="card" style="padding:0;overflow:hidden"><div style="padding:28px 24px;background:linear-gradient(120deg,#1F2B4B 0%,#2C4A3A 60%,#3F7A1E 100%);color:#fff;display:flex;gap:20px;align-items:center;flex-wrap:wrap"><span style="width:72px;height:72px;border-radius:18px;background:rgba(255,255,255,.95);display:grid;place-items:center;flex:none">${isoIcon('mirai',56)}</span><div style="flex:1;min-width:240px"><div style="font-size:13px;opacity:.8;font-weight:600">PUESTA EN MARCHA</div><h1 style="margin:2px 0 6px;font-size:26px">${first?`¡Bienvenido a Mirai${nombre?', '+esc(nombre):''}! Organicemos tus finanzas`:`Vas muy bien${nombre?', '+esc(nombre):''}`}</h1><p style="margin:0;opacity:.9;max-width:62ch">Sigue estos pasos en orden. Cada uno toma un par de minutos y le enseña al libro lo que necesita para avisarte, aconsejarte y mostrarte números exactos.</p></div>
    <div style="min-width:180px"><div style="font-size:30px;font-weight:800">${p.done} de ${p.total}</div><div style="height:8px;border-radius:4px;background:rgba(255,255,255,.2);overflow:hidden;margin-top:6px"><i style="display:block;height:100%;width:${p.done/p.total*100}%;background:#9EDB4E"></i></div><div style="font-size:12.5px;opacity:.85;margin-top:4px">pasos completados</div></div></div></div>
  ${p.next?`<div class="card ai-card"><div style="display:flex;gap:14px;align-items:center;flex-wrap:wrap"><span class="ri t-green" style="width:48px;height:48px;border-radius:50%;display:grid;place-items:center">${ic(p.next.icon)}</span><div style="flex:1;min-width:200px"><div class="lbl-s">SIGUIENTE PASO</div><h2>${p.next.t}</h2><p class="note" style="font-size:14px">${p.next.d}</p></div><button class="btn pri lg" ${act(p.next)}>${p.next.btn}${ic('arrow-right')}</button></div></div>`
   :`<div class="card">${empty('party-popper','¡Listo! Tu libro está configurado. Desde ahora te avisaremos de pagos y te ayudaremos a decidir antes de gastar.',`<button class="btn pri" data-act="setupFinish">${ic('house')}Ir al inicio</button>`)}</div>`}
  <div class="card"><div class="list">${p.st.map((s,i)=>`<div class="rowi" style="align-items:flex-start;padding:14px 8px"><span style="position:relative;flex:none">${isoIcon(SISO[s.k],44)}${s.ok?`<span class="step-ok">${ic('check')}</span>`:''}</span><div class="rb"><div class="rt" style="white-space:normal">${s.t} ${s.ok?'<span class="pill ok">Hecho</span>':s.skipped?'<span class="pill gray">Omitido</span>':''}</div><div class="note" style="white-space:normal;margin-top:2px">${s.d}</div></div><div class="ra" style="flex-wrap:wrap;justify-content:flex-end">${s.ok?`<button class="btn sm ghost" ${act(s)}>Agregar más</button>`:`<button class="btn sm ${s===p.next?'pri':'soft'}" ${act(s)}>${s.btn}</button>${s.skip&&!s.skipped?`<button class="btn sm ghost" data-act="setupSkip" data-k="${s.k}">${s.skip}</button>`:''}${s.skipped?`<button class="btn sm ghost" data-act="setupUnskip" data-k="${s.k}">Deshacer</button>`:''}`}</div></div>`).join('')}</div></div>
  <div class="card" style="flex-direction:row;align-items:center;gap:12px;flex-wrap:wrap"><span class="note" style="flex:1;min-width:220px">¿Quieres ver primero cómo se ve un libro lleno? Puedes cargar datos de ejemplo y volver a empezar cuando quieras desde Ajustes.</span><button class="btn" data-act="loadsample">${ic('eye')}Ver un ejemplo</button><button class="btn ghost" data-act="setupDismiss">Ocultar esta guía</button></div>`};

/* ================= vistas ================= */

V.inicio=()=>{const SP=setupProgress();const setupBanner=!setupDone()?`<div class="card ai-card" style="flex-direction:row;align-items:center;gap:14px;flex-wrap:wrap"><span class="ri t-green" style="width:44px;height:44px;border-radius:50%;display:grid;place-items:center">${ic('rocket')}</span><div style="flex:1;min-width:200px"><b>Completa la puesta en marcha (${SP.done} de ${SP.total})</b><div class="note">Siguiente: ${SP.next?SP.next.t:''}</div><div class="track" style="margin-top:6px"><i style="width:${SP.done/SP.total*100}%;background:#9EDB4E"></i></div></div><button class="btn pri" data-go="puesta">Continuar${ic('arrow-right')}</button></div>`:'';const T=totales(),t=today(),H=hormigas(),q=quincena(t.getFullYear(),t.getMonth(),t.getDate()<=S.cfg.corteQ?'q1':'q2'),N=notifs().slice(0,4),Ag=agenda().filter(x=>x.d<=15).slice(0,6);const nombre=(S.perfil.nombre||'').split(' ')[0];
  const max=Math.max(...H.meses.map(m=>m.v),1);
  return sampleBar()+setupBanner+`
  <div class="card"><form data-form="nl" class="composer card" style="box-shadow:none;padding:0">${av(S.perfil.nombre)}<input class="cp" name="texto" autocomplete="off" placeholder="Escribe lo que pasó, ${nombre?esc(nombre)+': ':''}“gasté 15 mil en almuerzo ayer”" aria-label="Registrar en palabras" style="color:var(--ink)"><button class="btn ai">${ic('sparkles')}Registrar</button></form><p class="note" style="margin:-4px 0 0 50px">La IA entiende frases como “pagué 120 mil de la luz” o “me pagaron 300 mil por un trabajo”.</p>
    <div class="quick"><button data-modal="gasto">${isoIcon('gastos',26)}Gasto</button><button data-modal="loan" data-kind="cobrar">${isoIcon('me-deben',26)}Presté dinero</button><button data-modal="fijo">${isoIcon('fijos',26)}Gasto fijo</button><button data-go="consejero">${isoIcon('consejero',26)}¿Me alcanza?</button></div></div>
  <section class="grid g4">
    ${kpi('scale','t-blue','Lo que tienes menos lo que debes',$(T.pat),'Patrimonio neto',T.pat<0?'neg':'')}
    ${kpi('wallet',q.disp>=0?'t-green':'t-red',`Te queda esta quincena`,$(q.disp),`Entra ${$k(q.E)} · sale ${$k(q.Sa)}`,q.disp<0?'neg':'pos')}
    ${kpi('landmark','t-red','Cuotas de deudas al mes',$(cuotasMes('pagar')),`Te deben ${$k(T.xc)} en total`)}
    ${kpi('coffee',H.over?'t-amber':'t-gray','Gastos hormiga este mes',$(H.totalMes),H.over?'Por encima de tu límite':'Dentro de tu límite',H.over?'wrn':'')}
  </section>
  <section class="grid g21">
    <div class="card"><div class="ph"><h2>${t.getDate()<=S.cfg.corteQ?'Primera':'Segunda'} quincena de ${MESL[t.getMonth()]}</h2><a href="#balance" data-act="balq">Ver detalle</a></div>
      <div class="taccount"><div><h3>Entra <span class="pill ok">${$(q.E)}</span></h3>${q.ent.slice(0,5).map(x=>`<div class="tline"><span class="ti t-green">${ic(x.icon)}</span><span class="tn">${esc(x.n)}<small>${esc(x.s)}</small></span><span class="num">${$(x.v)}</span><span>${x.paid?ic('circle-check','pos'):''}</span></div>`).join('')||'<p class="note">Sin entradas en esta quincena.</p>'}</div>
      <div><h3>Sale <span class="pill bad">${$(q.Sa)}</span></h3>${q.sal.slice(0,5).map(x=>`<div class="tline"><span class="ti t-red">${ic(x.icon)}</span><span class="tn">${esc(x.n)}<small>${esc(x.s)}</small></span><span class="num">${$(x.v)}</span><span>${x.paid?ic('circle-check','pos'):''}</span></div>`).join('')||'<p class="note">Sin salidas.</p>'}${q.sal.length>5?`<p class="note">y ${q.sal.length-5} más…</p>`:''}</div></div>
      <div class="band" style="background:${q.disp>=0?'var(--green-soft)':'var(--red-soft)'}"><div><b>${q.disp>=0?'Te sobra':'Te falta'}</b><div class="note">Entradas menos salidas de la quincena</div></div><span class="bv ${q.disp>=0?'pos':'neg'}">${$(Math.abs(q.disp))}</span></div></div>
    <div class="grid" style="align-content:start">
      <div class="card ai-card"><div class="ph"><h2 style="display:flex;gap:10px;align-items:center">${isoIcon('consejero',32)}Consejero antes de gastar</h2></div><p class="note" style="font-size:14px">¿Vas a comprar algo, prestar plata o sacar un crédito? Cuéntame el valor y te digo si te alcanza, con base en tus ingresos y gastos.</p><button class="btn ai" data-go="consejero">${ic('wand-sparkles')}Preguntar al consejero</button></div>
      <div class="card"><div class="ph"><h2>Avisos</h2><button class="btn ghost sm" data-act="bell">Ver todos</button></div>${N.length?N.map(n=>`<a class="nitem" href="#${n.go}" style="padding:6px"><span class="ni ${n.bg}" style="width:40px;height:40px">${ic(n.icon)}</span><span class="nb"><b>${esc(n.t)}</b><br><span class="note">${esc(n.b)}</span></span></a>`).join(''):empty('circle-check','Todo al día. No tienes avisos.')}</div>
    </div>
  </section>
  <section class="grid g3">
    <div class="card"><div class="ph"><h2>Próximos 15 días</h2><a href="#recordatorios">Ver todos</a></div><div class="list">${Ag.map(agRow).join('')||empty('calendar','Nada pendiente en los próximos 15 días.')}</div></div>
    <div class="card"><div class="ph"><h2>Metas</h2><a href="#metas">Ver</a></div><div class="bars">${S.metas.map(m=>bar(esc(m.nombre),m.ahorrado,m.objetivo,'#1F2B4B',pct(m.objetivo?m.ahorrado/m.objetivo:0,0),m.icon||'target')).join('')||empty('target','Aún no tienes metas.')}</div>
      <h2 style="margin-top:6px">Gasto hormiga</h2><svg viewBox="0 0 300 96" width="100%" role="img" aria-label="Gasto hormiga de los últimos seis meses">${H.meses.map((m,i)=>{const h=m.v/max*66;return `<rect x="${i*50+12}" y="${74-h}" width="26" height="${h}" rx="5" fill="${i===5?'#F7B928':'var(--line-2)'}"/><text x="${i*50+25}" y="90" text-anchor="middle" font-size="11" fill="var(--muted)">${m.l}</text>`}).join('')}</svg></div>
    <div class="card"><div class="ph"><h2>Préstamos</h2><a href="#me-deben">Ver</a></div><div class="bars">${[...S.cobrar.map(L=>[L,'cobrar']),...S.pagar.map(L=>[L,'pagar'])].map(([L,k])=>{const e=engine(L);return bar(`${esc(loanName(L,k))} <span class="pill ${k==='cobrar'?'ok':'bad'}">${k==='cobrar'?'me debe':'le debo'}</span>`,e.progreso,1,k==='cobrar'?'#3F7A1E':'#E41E3F',pct(e.progreso,0))}).join('')||empty('handshake','Sin préstamos registrados.')}</div></div>
  </section>`};
const agRow=x=>`<div class="rowi">${dateBox(x.fecha)}<div class="rb"><div class="rt">${esc(x.titulo)}</div><div class="rs">${esc(x.sub)} · <span class="pill ${x.st==='ok'?'gray':x.st}">${x.lbl}</span></div></div><div class="rv ${x.dir==='cobrar'?'pos':''}">${x.dir==='cobrar'?'+':''}${$(x.monto)}</div>${x.k==='fijo'?`<button class="btn sm soft" data-modal="pagarFijo" data-id="${x.id}" data-per="${x.per}">Pagar</button>`:x.k==='pagar'||x.k==='cobrar'?`<button class="btn sm soft" data-modal="pago" data-kind="${x.k}" data-id="${x.id}">${x.k==='cobrar'?'Cobrar':'Pagar'}</button>`:x.k==='sub'?`<button class="btn sm soft" data-act="subdone" data-id="${x.id}">Pagada</button>`:''}</div>`;

/* ---- balance y quincenas ---- */
let BAL={tab:'general',y:today().getFullYear(),m:today().getMonth()};
const PUC_A=[['1105','Efectivo','banknote'],['1110','Cuenta bancaria','landmark'],['1516','Inmueble (casa, lote)','house'],['1540','Vehículo','car'],['1995','Otro bien','tag']],PUC_P=[['2380','Tarjeta de crédito','credit-card'],['2381','Deuda informal','hand-coins'],['2408','Impuestos por pagar','receipt'],['2895','Otra deuda','tag']];
const pucIcon=c=>([...PUC_A,...PUC_P].find(x=>x[0]===c)||[0,0,String(c).startsWith('1')?'wallet':'receipt'])[2];
V.balance=()=>{const tabs=[['general','Lo que tengo y lo que debo','scale'],['q1','1ª quincena','calendar'],['q2','2ª quincena','calendar'],['mes','Mes completo','calendar-days']];
  let body='';
  if(BAL.tab==='general'){const T=totales();
    const line=(x,side)=>`<div class="tline"><span class="ti ${side==='activos'?'t-green':'t-red'}">${ic(x.icon||pucIcon(x.cod))}</span><span class="tn">${esc(x.nombre)}<small>${x.link?'Se calcula solo desde '+x.link:x.moneda&&x.moneda!=='COP'?`${fx(x.valor,x.moneda)} × ${$(S.cfg.trm[x.moneda])}`:'PUC '+esc(x.cod)}</small></span><span class="num">${$(x.link?x.valor:conv(x.valor,x.moneda))}</span>${x.link?'<span></span>':`<button class="btn icon sm ghost" data-act="del" data-col="${side}" data-id="${x.id}" aria-label="Eliminar">${ic('trash-2')}</button>`}</div>`;
    const act=[...S.activos,...(T.xi?[{nombre:'Inversiones',valor:T.xi,link:'Inversiones',icon:'trending-up'}]:[]),...(T.xc?[{nombre:'Lo que me deben',valor:T.xc,link:'Me deben',icon:'hand-coins'}]:[])];
    const pas=[...S.pasivos,...(T.xp?[{nombre:'Créditos y préstamos',valor:T.xp,link:'Le debo',icon:'landmark'}]:[])];
    body=`<div class="taccount"><div><h3>Lo que tengo <span class="lbl-s">ACTIVOS · DEBE</span></h3>${act.map(x=>line(x,'activos')).join('')||'<p class="note">Agrega tus cuentas, efectivo y bienes.</p>'}<div class="ttotal"><span>Total</span><span class="num pos">${$(T.A)}</span></div></div>
      <div><h3>Lo que debo <span class="lbl-s">PASIVOS · HABER</span></h3>${pas.map(x=>line(x,'pasivos')).join('')||'<p class="note">Sin deudas registradas.</p>'}<div class="ttotal"><span>Total</span><span class="num neg">${$(T.P)}</span></div></div></div>
      <div class="band"><div><b>Patrimonio</b><div class="note">Lo que tengo − lo que debo</div></div><span class="bv ${T.pat>=0?'pos':'neg'}">${$(T.pat)}</span></div>
      <p class="note">Tus gastos del mes (arriendo, mercado, servicios) no van aquí: regístralos en Gastos fijos o Gastos. Aquí solo van bienes que tienes y deudas que debes.</p>`}
  else{const q=quincena(BAL.y,BAL.m,BAL.tab);const it=(x,c)=>`<div class="tline"><span class="ti ${c}">${ic(x.icon)}</span><span class="tn">${esc(x.n)}<small>${esc(x.s)}</small></span><span class="num">${$(x.v)}</span><span>${x.paid?`<span class="pill ok">${ic('check')}Hecho</span>`:''}</span></div>`;
    body=`<div class="ph"><div class="row" style="display:flex;gap:8px;align-items:center"><button class="btn icon sm" data-act="balm" data-d="-1" aria-label="Mes anterior">${ic('chevron-left')}</button><b style="text-transform:capitalize;min-width:140px;text-align:center">${MESL[BAL.m]} ${BAL.y}</b><button class="btn icon sm" data-act="balm" data-d="1" aria-label="Mes siguiente">${ic('chevron-right')}</button></div><span class="note">Del ${fshort(q.a)} al ${fshort(q.b)}</span></div>
      <section class="grid g3">${kpi('arrow-down-to-line','t-green','Entra',$(q.E),q.ent.length+' movimientos','pos')}${kpi('arrow-up-from-line','t-red','Sale',$(q.Sa),q.sal.length+' movimientos','neg')}${kpi('wallet',q.disp>=0?'t-blue':'t-red',q.disp>=0?'Te sobra':'Te falta',$(Math.abs(q.disp)),'Disponible del periodo',q.disp>=0?'':'neg')}</section>
      <div class="taccount"><div><h3>Entradas <span class="lbl-s">DEBE</span></h3>${q.ent.map(x=>it(x,'t-green')).join('')||'<p class="note">Sin entradas. Registra tus ingresos en Mi dinero › Ingresos.</p>'}<div class="ttotal"><span>Total</span><span class="num pos">${$(q.E)}</span></div></div><div><h3>Salidas <span class="lbl-s">HABER</span></h3>${q.sal.map(x=>it(x,'t-red')).join('')||'<p class="note">Sin salidas.</p>'}<div class="ttotal"><span>Total</span><span class="num neg">${$(q.Sa)}</span></div></div></div>`}
  return pageH('scale','b-green','Balance y quincenas','Mira lo que tienes y lo que debes, o cuánto entra y sale en cada quincena del mes.',BAL.tab==='general'?`<button class="btn pri" data-modal="activo">${ic('plus')}Agregar cuenta o bien</button>`:'')+
  `<div class="card"><div class="tabs">${tabs.map(([k,l,i])=>`<button class="${BAL.tab===k?'on':''}" data-act="baltab" data-t="${k}">${ic(i)}${l}</button>`).join('')}</div>${body}</div>`};

/* ---- ingresos ---- */
V.ingresos=()=>{const ing=ingresoMensual();const t=today();const q1=quincena(t.getFullYear(),t.getMonth(),'q1').ent.filter(x=>x.icon==='briefcase').reduce((a,x)=>a+x.v,0),q2=quincena(t.getFullYear(),t.getMonth(),'q2').ent.filter(x=>x.icon==='briefcase').reduce((a,x)=>a+x.v,0);
  return pageH('arrow-down-to-line','b-green','Ingresos','Tu salario, honorarios, arriendos y cualquier dinero que recibas con regularidad.',`<button class="btn pri" data-modal="ingreso">${ic('plus')}Agregar ingreso</button>`)+`
  <section class="grid g3">${kpi('wallet','t-green','Ingreso mensual',$(ing),S.ingresos.length+' fuentes')}${kpi('calendar','t-blue',`1ª quincena (1–${S.cfg.corteQ})`,$(q1),'Lo que te entra')}${kpi('calendar','t-blue',`2ª quincena (${S.cfg.corteQ+1}–fin)`,$(q2),'Lo que te entra')}</section>
  <div class="card"><div class="list">${S.ingresos.map(x=>{const ci=S.cfg.catIngreso.find(c=>c.nombre===x.cat);return `<div class="rowi"><span class="ri t-green">${ic(ci?.icon||'coins')}</span><div class="rb"><div class="rt">${esc(x.concepto)}${x.bruto?' <span class="pill ok">neto</span>':''}</div><div class="rs">${esc(x.cat||'Ingreso')} · ${{mensual:'Cada mes'+(x.dia?' el día '+x.dia:''),quincenal:'Cada quincena (15 y 30)',semanal:'Cada semana',anual:'Una vez al año'}[x.frec]} · ${esc(quienName(x.quien))}</div>${dedLine(x)}</div><div class="rv pos">${fx(x.valor,x.moneda)}</div><div class="ra"><button class="btn icon sm ghost" data-modal="ingreso" data-id="${x.id}" aria-label="Editar">${ic('pencil')}</button><button class="btn icon sm ghost" data-act="del" data-col="ingresos" data-id="${x.id}" aria-label="Eliminar">${ic('trash-2')}</button></div></div>`}).join('')||empty('briefcase','Aún no registras ingresos.',`<button class="btn pri" data-modal="ingreso">${ic('plus')}Agregar el primero</button>`)}</div></div>`};

/* ---- gastos ---- */
let GMES=mkey(today());
V.gastos=()=>{const H=hormigas(),G=gastosMesK(GMES).sort((a,b)=>b.fecha.localeCompare(a.fecha)),tot=G.reduce((a,g)=>a+ +g.valor,0);const cats=Object.entries(H.porCat).sort((a,b)=>b[1].v-a[1].v),mx=Math.max(...cats.map(c=>c[1].v),1);
  const byDay={};G.forEach(g=>(byDay[g.fecha]=byDay[g.fecha]||[]).push(g));const mopts=[];for(let j=0;j<12;j++){const d=addMonths(new Date(today().getFullYear(),today().getMonth(),1),-j);mopts.push({v:mkey(d),l:`${MESL[d.getMonth()]} ${d.getFullYear()}`})}
  const al=[];if(H.over)al.push(alertBox('warn','triangle-alert',`Vas camino a gastar ${$(H.proy)} en gastos hormiga este mes`,`Tu límite es ${$(S.cfg.limite)}. En un año serían ${$(H.anual)}.`));cats.filter(c=>c[1].n>=6).forEach(c=>al.push(alertBox('warn',catIcon(c[0]),`${esc(c[0])}: ${c[1].n} compras este mes`,`Suman ${$(c[1].v)}. Al año serían unos ${$(c[1].v/today().getDate()*30*12)}.`)));
  return pageH('receipt','b-red','Gastos y hormiga',`Todo lo que gastas. La IA detecta los gastos "hormiga": pequeños, frecuentes y evitables, que juntos suman mucho. También puedes marcarlos tú con el ícono de la taza.`,`<button class="btn" data-modal="gasto" data-foto="1">${ic('camera')}Foto de factura</button><button class="btn ai" data-act="reviewH">${ic('sparkles')}Revisar hormiga con IA</button><button class="btn pri" data-modal="gasto">${ic('plus')}Registrar gasto</button>`)+`
  <section class="grid g21"><div class="card"><div class="ph"><h2>Gastos hormiga de este mes</h2><span class="pill ${H.over?'warn':'ok'}">${H.over?'Sobre el límite':'En rango'}</span></div>
    <div class="grid g3" style="gap:10px"><div class="metric"><b>${$(H.totalMes)}</b><span>Llevas</span></div><div class="metric"><b>${$(H.proy)}</b><span>Proyección del mes</span></div><div class="metric"><b>${$(H.anual)}</b><span>En un año</span></div></div>
    <div class="bars">${cats.map(([c,o])=>bar(`${esc(c)} <span class="mut">×${o.n}</span>`,o.v,mx,'#F7B928',$(o.v),catIcon(c))).join('')||'<p class="note">Sin gastos hormiga este mes.</p>'}</div></div>
    <div class="grid" style="align-content:start">${al.join('')||alertBox('ok','circle-check','Sin alertas','Tus gastos pequeños están bajo control.')}</div></section>
  <div class="card"><div class="ph"><h2>Movimientos</h2><div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><span class="note">${G.length} gastos · <b class="num">${$(tot)}</b></span><div style="width:200px">${sel('gmes',mopts,GMES,{attrs:'data-ui="gmes"'})}</div></div></div>
    ${Object.entries(byDay).map(([d,l])=>`<div><div class="lbl-s" style="padding:6px 0">${relTime(parse(d))==='Hoy'||relTime(parse(d))==='Ayer'?relTime(parse(d))+' · ':''}${fdate(parse(d))}</div><div class="list">${l.map(g=>`<div class="rowi"><span class="ri ${isHormiga(g)?'t-amber':'t-gray'}">${ic(catIcon(g.cat))}</span><div class="rb"><div class="rt">${esc(g.desc)}</div><div class="rs">${esc(g.cat)} · ${esc(quienName(g.quien))}${g.medio?' · '+esc(g.medio):''}${isHormiga(g)?` <span class="pill warn" title="${esc(g.hormigaRazon||'')}">${g.hormigaSrc==='ia'?ic('sparkles'):g.hormigaSrc==='manual'?ic('pencil'):''}hormiga</span>`:''}${g.fijoId?' <span class="pill info">fijo</span>':''}</div></div><div class="rv">${$(g.valor)}</div>${g.fijoId?'':`<button class="btn icon sm ghost" data-act="toggleH" data-id="${g.id}" title="${isHormiga(g)?'Quitar de hormiga':'Marcar como hormiga'}" aria-label="${isHormiga(g)?'Quitar de hormiga':'Marcar como hormiga'}" style="${isHormiga(g)?'color:#D98300':''}">${ic('coffee')}</button>`}<button class="btn icon sm ghost" data-act="del" data-col="gastos" data-id="${g.id}" aria-label="Eliminar">${ic('trash-2')}</button></div>`).join('')}</div></div>`).join('')||empty('receipt','No hay gastos en este mes.')}</div>`};

/* ---- gastos fijos ---- */
V.fijos=()=>{const t=today(),k=mkey(t);const st=S.fijos.map(f=>({f,s:fijoStatus(f)}));const venc=st.reduce((a,x)=>a+x.s.venc.length,0);
  const pendMes=st.reduce((a,{f,s})=>a+s.periods.filter(p=>!p.pago&&mkey(p.due)===k).reduce((b)=>b+ +f.valor,0),0),pagMes=st.reduce((a,{f})=>a+f.pagos.filter(p=>p.fecha&&p.fecha.startsWith(k)).reduce((b,p)=>b+ +p.valor,0),0);
  return pageH('house','b-blue','Gastos fijos','Arriendo, servicios, administración, colegio… lo que pagas cada mes. Te avisamos antes de cada fecha y, al pagar, queda registrado en tus gastos.',`<button class="btn pri" data-modal="fijo">${ic('plus')}Agregar gasto fijo</button>`)+`
  <section class="grid g3">${kpi('house','t-blue','Total al mes',$(fijosMes()),S.fijos.length+' gastos fijos')}${kpi('clock','t-amber','Falta pagar este mes',$(pendMes),`Ya pagaste ${$(pagMes)}`)}${kpi('circle-alert',venc?'t-red':'t-green','Vencidos',String(venc),venc?'Págalos cuanto antes':'Todo al día',venc?'neg':'')}</section>
  <div class="card"><div class="list">${st.map(({f,s})=>{const v=s.venc[0],p=v||s.prox;const stt=v?['bad','Vencido '+relTime(v.due).toLowerCase()]:p?[days(t,p.due)<=S.cfg.anticipo?'warn':'gray',relTime(p.due)]:['ok','Al día'];
    return `<div class="rowi"><span class="ri t-blue">${ic(catIcon(f.cat))}</span><div class="rb"><div class="rt">${esc(f.nombre)} ${f.variable?'<span class="pill gray">varía según consumo</span>':''}</div><div class="rs">${esc(f.cat)} · ${FFREC[f.frec]}${p?' · próximo: '+fdate(p.due)+(/-Q1$/.test(p.per)?' (1ª quinc.)':/-Q2$/.test(p.per)?' (2ª quinc.)':''):''}${f.proveedor?' · '+esc(f.proveedor):''} · <span class="pill ${stt[0]}">${stt[1]}</span></div></div><div class="rv">${f.variable&&f.vmin?`<span style="white-space:nowrap">${$(f.vmin)} – ${$(f.vmax)}</span><span class="note" style="display:block;font-size:12px;font-weight:400">promedio ${$(f.valor)}</span>`:$(f.valor)}</div><div class="ra">${p?`<button class="btn sm ${v?'pri':'soft'}" data-modal="pagarFijo" data-id="${f.id}" data-per="${p.per}">Pagar</button>`:''}<button class="btn icon sm ghost" data-modal="fijo" data-id="${f.id}" aria-label="Editar">${ic('pencil')}</button><button class="btn icon sm ghost" data-act="del" data-col="fijos" data-id="${f.id}" aria-label="Eliminar">${ic('trash-2')}</button></div></div>`}).join('')||empty('house','Aún no tienes gastos fijos. Empieza por el arriendo y los servicios.',`<button class="btn pri" data-modal="fijo">${ic('plus')}Agregar</button>`)}</div></div>
  <div class="card"><h2>Pagos registrados este mes</h2><div class="list">${st.flatMap(({f})=>f.pagos.filter(p=>p.fecha&&p.fecha.startsWith(k)).map(p=>`<div class="rowi"><span class="ri t-green">${ic('circle-check')}</span><div class="rb"><div class="rt">${esc(f.nombre)}</div><div class="rs">Pagado el ${fdate(parse(p.fecha))}${p.medio?' · '+esc(p.medio):''}</div></div><div class="rv">${$(p.valor)}</div><button class="btn sm ghost" data-act="unpayfijo" data-id="${f.id}" data-per="${p.per}">${ic('undo-2')}Deshacer</button></div>`)).join('')||'<p class="note">Aún no registras pagos este mes.</p>'}</div></div>`};

/* ---- suscripciones ---- */
function detectSubs(){const by={};S.gastos.filter(g=>!g.fijoId).forEach(g=>{const k=g.desc.toLowerCase().trim();(by[k]=by[k]||[]).push(g)});const names=S.suscripciones.map(s=>s.nombre.toLowerCase());const out=[];
  Object.entries(by).forEach(([k,l])=>{const ms=new Set(l.map(g=>g.fecha.slice(0,7)));if(ms.size<3)return;const vals=l.map(g=>+g.valor).sort((a,b)=>a-b),med=vals[Math.floor(vals.length/2)];if(vals.some(v=>Math.abs(v-med)>med*.15))return;if(l.length>ms.size*1.5)return;if(names.some(n=>k.includes(n)||n.includes(k)))return;out.push({desc:l[0].desc,valor:med,meses:ms.size,cat:l[0].cat})});return out}
V.suscripciones=()=>{const tot=subsMes(),D=detectSubs();
  return pageH('repeat','b-violet','Suscripciones','Streaming, apps, gimnasio y servicios que se cobran solos. Las que encontramos repetidas en tus gastos aparecen como sugerencia.',`<button class="btn pri" data-modal="sub">${ic('plus')}Agregar</button>`)+`
  <section class="grid g3">${kpi('repeat','t-violet','Te cuestan al mes',$(tot),S.suscripciones.length+' activas')}${kpi('calendar','t-red','En un año',$(tot*12),'Si no cancelas ninguna','neg')}${kpi('lightbulb','t-amber','Detectadas en tus gastos',String(D.length),'Cobros que se repiten')}</section>
  ${D.length?`<div class="card"><h2>¿Las sigues usando?</h2><div class="list">${D.map((d,i)=>`<div class="rowi"><span class="ri t-amber">${ic('lightbulb')}</span><div class="rb"><div class="rt">${esc(d.desc)}</div><div class="rs">Se repite en ${d.meses} meses · ${esc(d.cat)}</div></div><div class="rv">${$(d.valor)}</div><button class="btn sm soft" data-act="addsub" data-i="${i}">Agregar</button></div>`).join('')}</div></div>`:''}
  <div class="card"><div class="list">${S.suscripciones.map(s=>`<div class="rowi">${subAv(s.nombre,s.logo)}<div class="rb"><div class="rt">${esc(s.nombre)}${+s.comparte>1?` <span class="pill gray">compartida entre ${s.comparte}</span>`:''}</div><div class="rs">${s.ciclo==='anual'?'Anual':'Mensual'} · próximo cobro ${fdate(parse(s.proximo))}${s.medio?' · '+esc(s.medio):''} · tu parte: ${$(subMensual(s)*12)} al año</div></div><div class="rv">${fx(s.valor,s.moneda)}</div><button class="btn icon sm ghost" data-act="del" data-col="suscripciones" data-id="${s.id}" aria-label="Eliminar">${ic('trash-2')}</button></div>`).join('')||empty('repeat','Sin suscripciones registradas.')}</div></div>`};

/* ---- importar ---- */
let IMP=null;
const SAMPLE_CSV=`Fecha;Descripción;Valor\n${(()=>{const t=today();const d=n=>{const x=addDays(t,-n);return `${String(x.getDate()).padStart(2,'0')}/${String(x.getMonth()+1).padStart(2,'0')}/${x.getFullYear()}`};return [[1,'COMPRA EXITO CALLE 80','-245.300,00'],[2,'RAPPI*RESTAURANTE','-38.900,00'],[3,'PAGO NOMINA','4.750.000,00'],[4,'JUAN VALDEZ CAFE','-9.800,00'],[5,'UBER TRIP','-17.400,00'],[6,'TERPEL EDS','-160.000,00'],[8,'CUOTA DE MANEJO','-14.900,00'],[9,'FARMACIA','-52.000,00']].map(r=>`${d(r[0])};${r[1]};${r[2]}`).join('\n')})()}`;
function pnum(s){s=String(s).replace(/[^\d,.\-]/g,'');if(!s)return NaN;const c=s.lastIndexOf(','),p=s.lastIndexOf('.');if(c>-1&&p>-1){s=c>p?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,'')}else if(c>-1){s=/,\d{1,2}$/.test(s)?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,'')}else if(p>-1&&/\.\d{3}(\.|$)/.test(s)&&!/\.\d{1,2}$/.test(s))s=s.replace(/\./g,'');return parseFloat(s)}
function pdate(s){s=String(s).trim();let m=s.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);if(m)return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;m=s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})/);if(m){const y=m[3].length===2?'20'+m[3]:m[3];return `${y}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`}return null}
const classify=desc=>{const d=desc.toLowerCase();const r=S.cfg.reglas.find(x=>x.k&&d.includes(x.k.toLowerCase()));return r?r.cat:'Otros'};
function parseCSV(txt){const lines=txt.split(/\r?\n/).filter(l=>l.trim());if(!lines.length)return{err:'El archivo está vacío.'};const sep=(lines[0].match(/;/g)||[]).length>=(lines[0].match(/,/g)||[]).length?';':(lines[0].includes('\t')?'\t':',');
  const split=l=>{const o=[];let cur='',q=false;for(const ch of l){if(ch==='"'){q=!q;continue}if(ch===sep&&!q){o.push(cur);cur='';continue}cur+=ch}o.push(cur);return o.map(x=>x.trim())};
  const rows=lines.map(split);const h=rows[0].map(x=>x.toLowerCase());let fi=h.findIndex(x=>/fecha|date/.test(x)),di=h.findIndex(x=>/desc|concepto|detalle|referencia|movimiento/.test(x)),vi=h.findIndex(x=>/valor|monto|importe|d[eé]bito|amount/.test(x));
  let start=1;if(fi<0||di<0||vi<0){if(pdate(rows[0][0])){fi=0;di=1;vi=rows[0].length-1;start=0}else return{err:'No encontré columnas de fecha, descripción y valor. Usa un encabezado como: Fecha;Descripción;Valor'}}
  const out=[];let skipped=0;for(let i=start;i<rows.length;i++){const r=rows[i];const f=pdate(r[fi]),v=pnum(r[vi]),de=r[di]||'';if(!f||!isFinite(v)){skipped++;continue}out.push({fecha:f,desc:de,valor:v,cat:classify(de),incl:v<0})}
  if(!out.some(o=>o.valor<0))out.forEach(o=>o.incl=true);out.forEach(o=>o.valor=Math.abs(o.valor));return{rows:out,skipped}}
V.importar=()=>pageH('file-up','b-teal','Importar extractos','Descarga el extracto de tu banca en línea en formato CSV y súbelo aquí. Los débitos se vuelven gastos y se clasifican solos con tus reglas.')+`
  <div class="card"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center"><label class="btn soft" for="impFile">${ic('upload')}Subir archivo CSV</label><input id="impFile" type="file" accept=".csv,.txt,text/csv" hidden><button class="btn" data-act="impsample">${ic('file-text')}Probar con un extracto de ejemplo</button></div>
  ${field('O pega aquí el contenido',`<textarea class="inp" id="impTxt" placeholder="Fecha;Descripción;Valor&#10;15/10/2026;COMPRA EXITO;-245.300,00">${IMP?esc(IMP.txt):''}</textarea>`,{hint:'Separador ; o , · fechas dd/mm/aaaa · valores como 1.234.567,89 o -45000'})}
  <div><button class="btn pri" data-act="impparse">${ic('search')}Leer movimientos</button></div></div>
  ${IMP&&IMP.err?alertBox('bad','circle-x','No se pudo leer el archivo',esc(IMP.err)):''}
  ${IMP&&IMP.rows?`<div class="card">${IMP.ai==='pensando'?alertBox('info','sparkles','La IA está clasificando tus movimientos…','Categoría y gastos hormiga se ajustan solos en unos segundos.'):IMP.ai==='ok'?alertBox('ok','sparkles','La IA ya clasificó los movimientos','Revisa y corrige lo que necesites antes de importar.'):''}<div class="ph"><h2>Revisa antes de importar</h2><span class="note">${IMP.rows.filter(r=>r.incl).length} de ${IMP.rows.length} seleccionados${IMP.skipped?` · ${IMP.skipped} líneas ignoradas`:''}</span></div>
    <div class="tbl-wrap"><table><thead><tr><th></th><th>Fecha</th><th>Descripción</th><th class="r">Valor</th><th style="min-width:200px">Categoría</th><th>Hormiga</th></tr></thead><tbody>${IMP.rows.map((r,i)=>`<tr><td><input type="checkbox" class="chk" aria-label="Importar fila" data-imp="${i}|incl" ${r.incl?'checked':''}></td><td class="nw">${fdate(parse(r.fecha))}</td><td>${esc(r.desc)}</td><td class="r num">${$(r.valor)}</td><td>${sel('impcat'+i,catOpts(),r.cat,{attrs:`data-imp="${i}|cat"`,search:true})}</td><td><input type="checkbox" class="chk" aria-label="Es gasto hormiga" data-imp="${i}|hormiga" ${r.hormiga?'checked':''}>${r.aiH?` <span class="mut">${ic('sparkles')}</span>`:''}</td></tr>`).join('')}</tbody></table></div>
    <div class="form" style="grid-template-columns:repeat(auto-fit,minmax(200px,max-content))">${field('¿De quién son estos gastos?',sel('impQ',quienOpts(),'familia',{id:'impQ'}))}<div class="f"><button class="btn pri" data-act="impgo">${ic('check')}Importar seleccionados</button></div><div class="f"><button class="btn" data-act="impclear">Descartar</button></div></div></div>`:''}`;

/* ---- préstamos ---- */
let SEL={cobrar:null,pagar:null},LTAB='plan';
function loansView(kind){const L=S[kind],isC=kind==='cobrar';if(!L.find(x=>x.id===SEL[kind]))SEL[kind]=L[0]?.id||null;const cur=L.find(x=>x.id===SEL[kind]);
  const tot=L.reduce((a,x)=>a+engine(x).saldo,0),mora=L.filter(x=>engine(x).mora>0).length;
  const list=L.map(x=>{const e=engine(x),st=loanStatus(e),nm=loanName(x,kind);return `<div class="rowi" data-act="selLoan" data-kind="${kind}" data-id="${x.id}" style="cursor:pointer;${x.id===SEL[kind]?'background:var(--blue-soft)':''}">${isC||x.acreedor?.kind==='contacto'?av(nm,'sm'):`<span class="ri t-blue" style="width:36px;height:36px">${ic('landmark')}</span>`}<div class="rb"><div class="rt">${esc(nm)}</div><div class="rs">${esc(x.concepto||SISTEMAS[x.sistema].n)} · ${stPill(st)}</div><div class="track" style="margin-top:6px"><i style="width:${e.progreso*100}%;background:${isC?'#3F7A1E':'#E41E3F'}"></i></div></div><div class="rv">${$(e.saldo)}</div></div>`}).join('');
  let det=empty(isC?'hand-coins':'landmark',isC?'Registra a quién le prestaste dinero y lleva el control de cada pago.':'Registra tus créditos y deudas para saber cuánto debes y cuándo pagar.',`<button class="btn pri" data-modal="loan" data-kind="${kind}">${ic('plus')}${isC?'Registrar préstamo':'Registrar deuda'}</button>`);
  if(cur){const e=engine(cur),st=loanStatus(e),nm=loanName(cur,kind),ct=isC?S.contactos.find(c=>c.id===cur.contactoId):cur.acreedor?.kind==='contacto'?S.contactos.find(c=>c.id===cur.acreedor.id):null;
    const tabs=[['plan','Plan de pagos','list-checks'],['hist',isC?'Pagos recibidos':'Pagos hechos','receipt'],...(ct?[['ct','Datos del contacto','id-card']]:[])];if(!tabs.find(t=>t[0]===LTAB))LTAB='plan';
    let tb='';
    if(LTAB==='plan')tb=loanPlanTab(cur,kind,e,isC);
    if(LTAB==='hist')tb=e.hist.length?`<div class="list">${[...e.hist].reverse().map((h,ix)=>`<div class="rowi"><span class="ri ${h.tipo==='abono'?'t-violet':'t-green'}">${ic(h.tipo==='abono'?'coins':'circle-check')}</span><div class="rb"><div class="rt">${h.tipo==='abono'?'Abono a la deuda':'Cuota '+h.n+' completa'}</div><div class="rs">${fdate(h.fecha)}${h.tipo==='abono'?' · '+(h.modo==='plazo'?'para terminar antes':'para bajar la cuota'):` · interés ${$(h.int)} + abono ${$(h.cap)}`} · quedó en ${$(h.saldo)}</div></div><div class="rv pos">${$(h.valor)}</div>${ix===0?`<button class="btn sm ghost" data-act="undoPago" data-kind="${kind}" data-id="${cur.id}" data-pid="${h.id}">${ic('undo-2')}Deshacer</button>`:''}</div>`).join('')}</div>`:empty('receipt','Aún no hay pagos registrados.');
    if(LTAB==='ct'&&ct)tb=contactCardBody(ct);
    const D=loanDetail(cur,kind);det=`<div class="ld">${D.head}${D.now}${D.tiles}${D.split}${D.acts}
      <div class="tabs">${tabs.map(([k,l,i])=>`<button class="${LTAB===k?'on':''}" data-act="ltab" data-t="${k}">${ic(i)}${l}</button>`).join('')}</div>${tb}</div>`}
  return pageH(isC?'hand-coins':'landmark',isC?'b-green':'b-red',isC?'Me deben':'Le debo',isC?'Personas o clientes que te deben dinero. Registra cada pago, sea la cuota exacta o un abono.':'Créditos con bancos y deudas con personas. Registra cada pago y mira cuánto te falta.',`${isC?'':`<button class="btn" data-act="empeno">${ic('gem')}Registrar empeño</button>`}<button class="btn pri" data-modal="loan" data-kind="${kind}">${ic('plus')}${isC?'Nuevo préstamo':'Nueva deuda'}</button>`)+`
  <section class="grid g3">${kpi(isC?'hand-coins':'landmark',isC?'t-green':'t-red',isC?'Total que te deben':'Total que debes',$(tot),L.length+(isC?' préstamos':' deudas'),isC?'pos':'neg')}${kpi('calendar','t-blue','Cuotas al mes',$(cuotasMes(kind)),isC?'Lo que deberías recibir':'Lo que debes pagar')}${kpi('circle-alert',mora?'t-red':'t-green','Atrasados',String(mora),mora?(isC?'Personas con pagos atrasados':'Deudas en mora'):'Ninguno',mora?'neg':'')}</section>
  <section class="grid g12 loans-grid"><div class="card" style="align-self:start"><h2>${isC?'Quién me debe':'A quién le debo'}</h2><div class="list">${list||'<p class="note" style="padding:0 8px">Sin registros.</p>'}</div></div><div class="card">${det}</div></section>`}
V['me-deben']=()=>loansView('cobrar');V['le-debo']=()=>loansView('pagar');

/* ---- contactos ---- */
const contactCardBody=c=>`<div class="grid g2" style="gap:12px">${[['phone','Teléfono',c.telefono,true],['mail','Correo',c.email,true],['id-card','Documento',c.doc?`${c.docTipo||''} ${c.doc}`:''],['map-pin','Dirección',[c.direccion,c.ciudad].filter(Boolean).join(', ')],['users','Relación',c.relacion],['info','Notas',c.notas]].map(([i,l,v,cp])=>`<div class="rowi" style="padding:6px 0"><span class="ri t-gray" style="width:36px;height:36px">${ic(i)}</span><div class="rb"><div class="lbl-s">${l}</div><div style="word-break:break-word">${v?esc(v):'<span class="mut">Sin registrar</span>'}</div></div>${cp&&v?`<button class="btn icon sm ghost" data-act="copy" data-v="${esc(v)}" aria-label="Copiar">${ic('copy')}</button>`:''}</div>`).join('')}</div>`;
V.contactos=()=>{const stats=c=>{const me=S.cobrar.filter(L=>L.contactoId===c.id).reduce((a,L)=>a+engine(L).saldo,0),yo=S.pagar.filter(L=>L.acreedor?.kind==='contacto'&&L.acreedor.id===c.id).reduce((a,L)=>a+engine(L).saldo,0);const mora=S.cobrar.filter(L=>L.contactoId===c.id&&engine(L).mora>0).length;return{me,yo,mora}};
  return pageH('users','b-amber','Contactos','Las personas y empresas con las que tienes préstamos. Guarda sus datos una vez y úsalos cada vez que registres un préstamo.',`<button class="btn pri" data-modal="contacto">${ic('plus')}Nuevo contacto</button>`)+
  (S.contactos.length?`<section class="grid g3">${S.contactos.map(c=>{const s=stats(c);return `<div class="card"><div style="display:flex;gap:12px;align-items:center">${av(c.nombre)}<div style="min-width:0;flex:1"><h3 style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(c.nombre)}</h3><div class="note">${esc(c.relacion||(c.tipo==='empresa'?'Empresa':'Persona'))}${c.ciudad?' · '+esc(c.ciudad):''}</div></div><button class="btn icon sm ghost" data-modal="contacto" data-id="${c.id}" aria-label="Editar">${ic('pencil')}</button></div>
    <div style="display:flex;flex-direction:column;gap:6px;font-size:14px">${c.telefono?`<span style="display:flex;gap:8px;align-items:center">${ic('phone','mut')}${esc(c.telefono)}</span>`:''}${c.doc?`<span style="display:flex;gap:8px;align-items:center">${ic('id-card','mut')}${esc(c.docTipo)} ${esc(c.doc)}</span>`:''}${c.direccion?`<span style="display:flex;gap:8px;align-items:center">${ic('map-pin','mut')}${esc(c.direccion)}</span>`:''}</div>
    <div class="grid g2" style="gap:8px"><div class="metric"><b class="pos">${$(s.me)}</b><span>Te debe</span></div><div class="metric"><b class="neg">${$(s.yo)}</b><span>Le debes</span></div></div>${s.mora?'<span class="pill bad">Tiene pagos atrasados</span>':''}
    <div style="display:flex;gap:8px"><button class="btn soft sm" style="flex:1" data-modal="loan" data-kind="cobrar" data-cid="${c.id}">${ic('hand-coins')}Prestarle</button><button class="btn icon sm ghost" data-act="delContact" data-id="${c.id}" aria-label="Eliminar">${ic('trash-2')}</button></div></div>`}).join('')}</section>`:`<div class="card">${empty('users','Aún no tienes contactos.',`<button class="btn pri" data-modal="contacto">${ic('plus')}Agregar contacto</button>`)}</div>`)};

/* ---- salir de deudas ---- */
let EX={extra:500000,abono:{id:null,v:2000000,modo:'plazo'}};
function sim(extra,order,roll=true){const D=S.pagar.map(L=>{const e=engine(L);return{n:loanName(L,'pagar')+(L.concepto?' · '+L.concepto:''),s:e.saldo,i:e.i,c:e.next?e.next.valor-(+L.extra||0):0}}).filter(d=>d.s>1);if(!D.length)return null;
  const budget=D.reduce((a,d)=>a+d.c,0)+extra;let m=0,ti=0;const pay={};const ord=[...D].sort(order);
  while(D.some(d=>d.s>1)&&m<600){m++;D.forEach(d=>{if(d.s>1){const int=d.s*d.i;d.s+=int;ti+=int}});let avl=budget;D.forEach(d=>{if(d.s>1){const p=Math.min(d.c,d.s);d.s-=p;avl-=p}});
    if(roll){avl=Math.max(avl,0);for(const o of ord){const d=D.find(x=>x.n===o.n);if(d.s>1&&avl>0){const p=Math.min(avl,d.s);d.s-=p;avl-=p}}}D.forEach(d=>{if(d.s<=1&&!pay[d.n])pay[d.n]=m})}
  return{m,ti,pay,ord:ord.map(o=>o.n)}}
V.estrategia=()=>{if(!S.pagar.length)return pageH('trending-down','b-amber','Salir de deudas','Compara formas de pagar tus deudas más rápido.')+`<div class="card">${empty('landmark','Registra tus créditos en Le debo para usar el simulador.',`<button class="btn pri" data-go="le-debo">Ir a Le debo</button>`)}</div>`;
  const base=sim(0,()=>0,false),ava=sim(+EX.extra,(a,b)=>b.i-a.i),bol=sim(+EX.extra,(a,b)=>a.s-b.s);
  if(!EX.abono.id||!S.pagar.find(p=>p.id===EX.abono.id))EX.abono.id=S.pagar[0].id;const L=S.pagar.find(x=>x.id===EX.abono.id);
  const e0=engine(L),L2=clone(L);L2.pagos.push({id:'sim',fecha:iso(today()),tipo:'abono',valor:EX.abono.v,modo:EX.abono.modo});const e1=engine(L2);
  const card=(t,icon,r,d)=>`<div class="card"><div class="ph"><h2 style="display:flex;gap:8px;align-items:center">${ic(icon)}${t}</h2><span class="pill info">${r.m} meses</span></div><p class="note">${d}</p><div class="grid g2" style="gap:8px"><div class="metric"><b>${$(r.ti)}</b><span>Pagarías en intereses</span></div><div class="metric"><b class="pos">${$(base.ti-r.ti)}</b><span>Te ahorras</span></div></div><div class="list">${r.ord.map((n,i)=>`<div class="rowi"><span class="ri t-blue" style="width:30px;height:30px;font-weight:700">${i+1}</span><div class="rb"><div class="rt">${esc(n)}</div></div><span class="note">terminas en el mes ${r.pay[n]}</span></div>`).join('')}</div></div>`;
  return pageH('trending-down','b-amber','Salir de deudas','Si cada mes pones un poco más de plata a tus deudas, terminas antes y pagas menos intereses. Aquí comparas dos métodos.')+`
  <div class="card"><div class="form" style="grid-template-columns:repeat(auto-fit,minmax(220px,max-content))">${field('¿Cuánto más puedes pagar al mes?',money('exE',EX.extra,{attrs:'data-ex="extra"'}),{hint:`Hoy pagas ${$(cuotasMes('pagar'))} en cuotas`})}</div>
    <div class="grid g3" style="gap:10px"><div class="metric"><b>${base.m} meses</b><span>Sin pagar extra</span></div><div class="metric"><b>${$(base.ti)}</b><span>Intereses sin pagar extra</span></div><div class="metric"><b class="pos">${ava.ti<=bol.ti?'Avalancha':'Bola de nieve'}</b><span>Método que más te conviene</span></div></div></div>
  <section class="grid g2">${card('Avalancha','zap',ava,'Pones el dinero extra a la deuda con el interés más alto. Es la que menos plata te cuesta.')}${card('Bola de nieve','sprout',bol,'Pones el dinero extra a la deuda más pequeña. Ves resultados rápido y te motiva a seguir.')}</section>
  <div class="card"><h2>¿Y si hago un abono extra a un crédito?</h2><div class="form">${field('Crédito',sel('abP',S.pagar.map(x=>({v:x.id,l:loanName(x,'pagar')+(x.concepto?' · '+x.concepto:''),icon:'landmark'})),EX.abono.id,{attrs:'data-ex="abono.id"'}))}${field('Valor del abono',money('abV',EX.abono.v,{attrs:'data-ex="abono.v"'}))}<div class="f"><span class="fl">¿Qué prefieres?</span><div class="seg">${pick('abmodo',[{v:'plazo',l:'Terminar antes'},{v:'cuota',l:'Pagar menos cada mes'}],EX.abono.modo,'')}</div></div></div>
    <div class="grid g4" style="gap:10px"><div class="metric"><b>${$(e0.saldo)} → ${$(e1.saldo)}</b><span>Lo que debes</span></div><div class="metric"><b>${e0.plan.length} → ${e1.plan.length}</b><span>Cuotas que faltan</span></div><div class="metric"><b>${e0.next?$(e0.next.valor):'—'} → ${e1.next?$(e1.next.valor):'—'}</b><span>Valor de la cuota</span></div><div class="metric"><b class="pos">${$(Math.max(e0.intTotal-e1.intTotal,0))}</b><span>Ahorro en intereses</span></div></div>
    <p class="note">Terminar antes casi siempre ahorra más intereses. Pagar menos cada mes te deja más plata libre. Cuando hagas el abono de verdad, regístralo en Le debo › Registrar pago › Abono.</p></div>`};
